sqlMap.select:
SELECT COUNT(*) FROM (SELECT ROWNUM EMPNUM, DATATABLEB.EV_PERIOD_ID, DATATABLEB.EV_EMP_ID, DATATABLEB.ACHIVE, DATATABLEB.ABILITY, DATATABLEB.EXPERIENCE, DATATABLEB.EDU, DATATABLEB.ADDSUB, DATATABLEB.TOTAL FROM (SELECT DATATABLE.EV_PERIOD_ID, DATATABLE.EV_EMP_ID, DATATABLE.ACHIVE, DATATABLE.ABILITY, DATATABLE.EXPERIENCE, DATATABLE.EDU, DATATABLE.ADDSUB, (NVL(DATATABLE.ACHIVE, 0) + NVL(DATATABLE.ABILITY, 0) + NVL(DATATABLE.EXPERIENCE, 0) + NVL(DATATABLE.EDU, 0) + NVL(DATATABLE.ADDSUB, 0)) TOTAL FROM (SELECT EE.EV_PERIOD_ID, EE.EV_EMP_ID, EE.EV_EMP_NAME, EE.EV_DEPT_ID, (SELECT EEIP.EV_ITEM_MARK FROM EVS_EMP_ITEM_PROCESS EEIP WHERE EEIP.EV_PERIOD_ID = EE.EV_PERIOD_ID AND EEIP.EV_EMP_ID = EE.EV_EMP_ID AND EEIP.EV_ITEM_ID = 'EVITEM002') ACHIVE, EE.EV_AVG_MARK AS ABILITY, (SELECT EEI.EV_EXTRA_ITEM_MARK FROM EV_EXTRA_ITEM EEI WHERE EEI.EV_PERIOD_ID = EE.EV_PERIOD_ID AND EEI.EV_EMPID = EE.EV_EMP_ID AND EEI.EV_EXTRA_ITEM_ID = 'EVEXTRAITEM001') EXPERIENCE, (SELECT EEI.EV_EXTRA_ITEM_MARK FROM EV_EXTRA_ITEM EEI WHERE EEI.EV_PERIOD_ID = EE.EV_PERIOD_ID AND EEI.EV_EMPID = EE.EV_EMP_ID AND EEI.EV_EXTRA_ITEM_ID = 'EVEXTRAITEM002') EDU, (SELECT EEI.EV_EXTRA_ITEM_MARK FROM EV_EXTRA_ITEM EEI WHERE EEI.EV_PERIOD_ID = EE.EV_PERIOD_ID AND EEI.EV_EMPID = EE.EV_EMP_ID AND EEI.EV_EXTRA_ITEM_ID = 'EVEXTRAITEM003') ADDSUB FROM EVS_EMP EE) DATATABLE ORDER BY TOTAL DESC, DATATABLE.EV_EMP_ID) DATATABLEB
) DATATABLEC
WHERE DATATABLEC.EV_EMP_ID = #EMPID#

SELECT HE.PERSON_ID, HE.EMPID, HE.LOCAL_NAME, HDM.ORG_NAME_LOCAL DEPT_NAME, HE.EMP_TYPE_CODE, g.content FROM HR_EMPLOYEE HE, HR_DEPARTMENT_NAME HD, HR_DEPARTMENT HDM, HR_PERSONAL_INFO HPI, SY_GLOBAL_NAME G WHERE HE.DEPTNO = HD.DEPTNO(+) AND HE.EMP_TYPE_CODE=G.NO(+) AND G.LANGUAGE=#interLanguage:VARCHAR# AND HD.LANGUAGE(+) = #interLanguage:VARCHAR# AND HE.DEPTNO = HDM.DEPTNO(+) AND HE.CPNY_ID = #CPNY_ID:VARCHAR# AND HE.PERSON_ID = HPI.PERSON_ID(+)
(HE.PERSON_ID = #PERSON_ID:VARCHAR# OR HE.DEPTNO IN
)
(HE.PERSON_ID = #PERSON_ID:VARCHAR# OR HE.EMP_TYPE_CODE IN
)
HE.PERSON_ID = #ADMIN_ID:VARCHAR#

